window.READER_EXTRA_HTML = "<section class=\"education-path\" aria-labelledby=\"education-path-title\"><div class=\"education-path__intro\"><p class=\"eyebrow\">One route, many entry points</p><h2 id=\"education-path-title\">A syllabus that grows with the model.</h2><p>Each shelf is generated from the versioned manifests and accessible editions in the SFT Edu directory. When a new edition becomes current, the previous edition moves into preserved history instead of disappearing.</p></div><div class=\"education-stage-grid\"><article class=\"education-stage-card\"><span>Early Years / Foundation</span><strong>4</strong><p>Shared reading, noticing, sorting, building and honest checking.</p></article><article class=\"education-stage-card\"><span>Ages 5–7</span><strong>0</strong><p>A first primary route through exact parts, patterns, records and simple machines.</p></article><article class=\"education-stage-card\"><span>Ages 7–11</span><strong>0</strong><p>Illustrated explanations, worked examples, practical activities and cumulative review.</p></article><article class=\"education-stage-card\"><span>Ages 11–14</span><strong>0</strong><p>Branch primers that introduce derivation, evidence, dependencies and open boundaries.</p></article><article class=\"education-stage-card\"><span>GCSE-age · roughly 14–16</span><strong>0</strong><p>Structured derivation, practical checks and evidence questions. GCSE-style, not an accredited qualification.</p></article><article class=\"education-stage-card\"><span>Post-16 · roughly 16–18</span><strong>0</strong><p>Proof, modelling, receipts, uncertainty and extended investigation.</p></article><article class=\"education-stage-card\"><span>Undergraduate introduction</span><strong>0</strong><p>Repository-facing reconstruction, independent certificates and critical audit.</p></article><article class=\"education-stage-card\"><span>Advanced study</span><strong>0</strong><p>Living handbooks for lawful extension, certification and frontier investigation.</p></article></div><aside class=\"education-qualification-note\"><strong>Clear qualification boundary</strong><p>GCSE-age materials use familiar learning and assessment styles, but they are not an approved GCSE specification or an accredited qualification. Exam-board mappings are navigation aids only.</p></aside><div class=\"education-provenance\"><div><span>Source revision</span><strong>b0691f43f76f</strong></div><div><span>Projection</span><strong>Committed Source</strong></div><div><span>Current books</span><strong>4</strong></div></div></section>";
